insert into roles(code,name) values('CEO','Chief Executive Officer'),('ADMIN','Administrator'),('PARTNER','Partner'),('INSTRUCTOR','Instructor'),('STUDENT','Student / Client') on conflict(code) do nothing;
insert into permissions(code,name) values('users.view','View users'),('users.manage','Manage users'),('packages.view','View packages'),('packages.manage','Manage packages'),('courses.view','View courses'),('courses.create','Create courses'),('courses.manage','Manage courses'),('orders.view','View orders'),('payments.verify','Verify payments'),('withdrawals.request','Request withdrawal'),('withdrawals.review','Review withdrawals'),('commission_rules.manage','Manage commission rules'),('audit_logs.view','View audit logs'),('learning.access','Access learning'),('profile.manage','Manage profile') on conflict(code) do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r cross join permissions p where r.code='CEO' on conflict do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r join permissions p on p.code in('users.view','courses.view','orders.view') where r.code='ADMIN' on conflict do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r join permissions p on p.code in('packages.view','courses.view','withdrawals.request','profile.manage') where r.code='PARTNER' on conflict do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r join permissions p on p.code in('courses.view','courses.create','courses.manage','profile.manage') where r.code='INSTRUCTOR' on conflict do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r join permissions p on p.code in('packages.view','courses.view','learning.access','profile.manage') where r.code='STUDENT' on conflict do nothing;
insert into levels(level_number,points_required) values(1,100),(2,250),(3,400),(4,500),(5,650),(6,800),(7,1000),(8,1500),(9,2000) on conflict(level_number) do update set points_required=excluded.points_required;
insert into packages(slug,name,subtitle,description,price_inr,display_order) values('aarambh','Aarambh','Digital Foundation','Build a strong digital foundation.',499,1),('udaan','Udaan','Creative + Content Skills','Build creative and content skills.',999,2),('pragati','Pragati','Marketing + Client Skills','Build marketing and client skills.',1999,3),('brahmastra','Brahmastra','Advanced Digital Skills','Build advanced digital skills.',3999,4),('shikhar','Shikhar','Leadership + Business','Build leadership and business skills.',6999,5) on conflict(name) do update set price_inr=excluded.price_inr;
insert into categories(name,slug) values('Digital Foundation','digital-foundation'),('Creative & Content','creative-content'),('Marketing & Client Skills','marketing-client-skills'),('Advanced Digital Skills','advanced-digital-skills'),('Leadership & Business','leadership-business') on conflict(name) do nothing;
insert into rewards(level_number,name,description) values(1,'Starter Recognition','Starter reward subject to eligibility and approval.'),(2,'Identity Reward','Level 2 reward subject to approval.'),(3,'T-shirt Reward','Level 3 reward subject to approval.'),(4,'Progress Reward','Level 4 reward subject to approval.'),(5,'Growth Reward','Level 5 reward subject to approval.'),(6,'Advanced Reward','Level 6 reward subject to approval.'),(7,'Elite Reward','Level 7 reward subject to approval.'),(8,'Premium Reward','Level 8 reward subject to approval.'),(9,'Leadership Reward','Level 9 reward subject to approval.') on conflict do nothing;
